(function(){'use strict';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const categories=['RPL','RPL Refresher','STEM','Industry Specific'];
const core=category=>['full_name','email','phone',...(category==='STEM'?['guardian_name','guardian_phone','guardian_consent']:[])];
function fields(category){return [{id:'full_name',label:category==='STEM'?'Child / learner full name':'Applicant full name',type:'text',required:true},{id:'email',label:category==='STEM'?'Parent / guardian email':'Contact email',type:'email',required:true},{id:'phone',label:category==='STEM'?'Parent / guardian contact phone':'Contact phone',type:'tel',required:true},{id:'date_of_birth',label:'Date of birth',type:'date',required:category==='STEM'},...(category==='STEM'?[{id:'guardian_name',label:'Parent / guardian full name',type:'text',required:true},{id:'guardian_phone',label:'Parent / guardian phone',type:'tel',required:true},{id:'guardian_consent',label:'I am the parent / authorised guardian and consent to this application',type:'checkbox',required:true}]:[])];}
function exampleSchedule(){const rows=[
 ['Introduction to drones','RPA Theory Review - Regulations',''],['ADM','Operating rules','Quiz 1 and 2'],['Emergency Procedures','RPA Theory Review - Aerodynamics','Quiz 3 and Revision'],['Runways','Airspaces','Quiz 5 and Revision'],['Sectional Charts','Questions and Answers','Quiz 6 & Video assignment'],
 ['Radiotelephony','Meteorology 1','Quiz 7 and Revision'],['Radiotelephony','Meteorology 2','Quiz and Revision'],['Radiotelephony','Radiotelephony','Quiz and Revision'],['Radiotelephony','Radiotelephony','Quiz and Revision'],['','Final Mock Exam',''],
 ['Flights at ABC','Medicals (ABC)','Medicals (Kamuzu Barracks)'],['Flights at ABC','RPL Theory Exams','Radiotelephony Simulator'],['Flights at ABC','Radiotelephony Mock Exam','Radiotelephony Simulator'],['Flights at ABC','Radiotelephony Exam','Radiotelephony Simulator'],['Flight Exam','Radiotelephony Practical Exam','Radiotelephony Practical Exam']];
 return rows.map((topics,i)=>({offset:Math.floor(i/5)*7+i%5,date:'',phase:`Week ${Math.floor(i/5)+1} - ${i<10?'Online':'In person'}`,slots:topics.map((topic,j)=>({time:(i<10?['14:30 - 16:30','18:30 - 20:30','TBD']:['07:00 - 09:00','09:30 - 11:30','13:00 - 15:00'])[j],topic}))}));}
function shiftSchedule(rows,start){if(!/^\d{4}-\d{2}-\d{2}$/.test(start))throw new Error('Choose the start date first');return rows.map((r,i)=>{const d=new Date(start+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+(Number.isFinite(r.offset)?r.offset:i));return {...r,date:d.toISOString().slice(0,10)};});}
function validate(c){if(!categories.includes(c.category)||!c.title.trim())throw new Error('Choose a course and enter a call title');if(!Array.isArray(c.fields)||c.fields.length>60)throw new Error('Use at most 60 fields');const ids=new Set();for(const f of c.fields){if(!/^[a-z][a-z0-9_]{0,49}$/.test(f.id)||ids.has(f.id)||!f.label.trim()||f.label.length>200)throw new Error('Every field needs a unique key and a label');ids.add(f.id);if(!['text','textarea','email','tel','date','number','select','checkbox'].includes(f.type))throw new Error('Choose a supported field type');if(f.type==='select'&&(!f.options?.length||f.options.length>50))throw new Error('Add choices to each select field');}for(const id of core(c.category))if(!c.fields.some(f=>f.id===id&&f.required))throw new Error('Keep required contact and guardian fields');if(c.fields.find(f=>f.id==='email')?.type!=='email'||(c.category==='STEM'&&c.fields.find(f=>f.id==='guardian_consent')?.type!=='checkbox'))throw new Error('Email and guardian-consent field types must be retained');
 if(c.schedule.length>120)throw new Error('Use at most 120 schedule days');for(const row of c.schedule){if(!row.phase.trim()||!Array.isArray(row.slots)||row.slots.length!==3)throw new Error('Each schedule day needs a phase and three slots');if(c.published&&!row.date)throw new Error('Set dates for every schedule day before publishing');}
 if(c.published&&['RPL','RPL Refresher'].includes(c.category)&&!c.schedule.length)throw new Error('Add the upcoming schedule before publishing this RPL call');if(c.published&&c.fee>0&&!c.payment_instructions.trim())throw new Error('Add payment instructions before publishing a paid course');return c;}
function scheduleHTML(c){if(!c.schedule?.length)return '<p class="cage-academy-muted">Schedule to be confirmed by CAGE.</p>';return `<div class="cage-academy-schedule"><div class="cage-academy-schedule-heading"><img src="./cage-logo-new.png" alt="CAGE" class="cage-academy-schedule-logo"><h3>${esc(c.title)} — schedule</h3><p>${esc(c.venue||'Venue to be confirmed')} · All times Malawi time</p></div>${c.schedule.map((r,i)=>`<article class="cage-academy-schedule-day"><div><strong>${r.date?esc(new Date(r.date+'T12:00:00Z').toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'short',year:'numeric'})):'Date to be confirmed'}</strong><span>${esc(r.phase)}</span></div>${r.slots.map(s=>`<section><small>${esc(s.time||'TBD')}</small><p>${esc(s.topic||'—')}</p></section>`).join('')}</article>`).join('')}<p class="cage-academy-preline">${esc(c.schedule_notes||'Schedule subject to change. Confirm dates with CAGE before travel.')}</p></div>`;}
window.CAGE_ADMISSIONS_COMMON={esc,categories,core,fields,exampleSchedule,shiftSchedule,validate,scheduleHTML};
})();
